import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"坎上坎下 坎：","description":"京氏易传 - 坎上坎下 坎：","frontmatter":{"title":"坎上坎下 坎：","description":"京氏易传 - 坎上坎下 坎："},"headers":[],"relativePath":"zh/classics/jingshi/018.md","filePath":"zh/classics/jingshi/018.md"}'),i={name:"zh/classics/jingshi/018.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"坎上坎下-坎",tabindex:"-1"},[l("坎上坎下 坎： "),e("a",{class:"header-anchor",href:"#坎上坎下-坎","aria-label":"Permalink to “坎上坎下 坎：”"},"​")],-1),e("p",null,"积阴，以阳处中。柔顺，不能履重刚之险。故以刚克柔而履险。而曰阳，是以坎为属中男。分北方之卦也，与离为飞伏。【戊子水，己巳火。】世立宗庙，居于阴位。比近九五，全于坎道，远于祸害。三公居应，亦为阴暗。成坎之德，在于九五、九二也。【内外居坎，阳处中而为坎。主纯阴得阳，为明臣得君，而安其居也。一作君得臣，而显其道也。】",-1),e("p",null,"建起戊寅至癸未，【大暑至大雪。】积算起癸未至壬午，周而复始。【金水入卦本同宫，气候起算时日岁月吉凶。】",-1),e("p",null,"五星从位起太白，【太白金星入水宫。】牛宿从位降戊子。【二十八宿，从位八卦，周而复始。】岁候运数三十六。【配六位，分阴阳；三百五十六，（虎易注：疑为三百六十五之误。）余日四分之一。分五行，配运气，吉凶见矣。】",-1),e("p",null,"内外俱坎，是重刚之位。《易》曰：“坎，陷也。”【坎水能深陷于物；处坎之险，不可不习。故曰：习坎。便习之习后，可得履于险而不陷没者。不以刚履柔，不能成坎之道也。】",-1),e("p",null,"震以阳居初，能震动于物，能为动主。【乾生震，一阳居于初，震为长男。】坎以阳居中，为重刚之主，故以坎为险。阳变阴，成于阴道。今以阴变阳，止于为节。【次入于节卦。】",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
